function normalizeData(value){const d=value&&typeof value==='object'?value:{};return {...d,road:d.road&&typeof d.road==='object'?d.road:{},skill:d.skill&&typeof d.skill==='object'?d.skill:{},reminders:Array.isArray(d.reminders)?d.reminders:[],mastery:d.mastery&&typeof d.mastery==='object'?d.mastery:{},visits:Array.isArray(d.visits)?d.visits:[],projects:d.projects&&typeof d.projects==='object'?d.projects:{},practiceDays:Array.isArray(d.practiceDays)?d.practiceDays:[],role:d.role||'frontend'}}let storageKey='bloompath',data={};try{data=normalizeData(JSON.parse(localStorage.getItem(storageKey)||'{}'))}catch(e){data=normalizeData({})}let page='home',roadFilter='all',skillFilter='all',cardFilter='all',cardIndex=0,flipped=false;
