function roadItems(){return P.flatMap((p,pi)=>p.i.map((x,ii)=>({id:pi+'-'+ii,track:x[0],text:x[1],phase:pi})))}function allSteps(){return K.flatMap(k=>k[3].map((s,i)=>({id:k[0]+i,track:k[0],text:s,stage:i})))}function rPct(){let a=roadItems(),n=a.filter(x=>data.road[x.id]).length;return {n,total:a.length,p:Math.round(100*n/a.length)}}function sPct(){let a=allSteps(),n=a.filter(x=>data.skill[x.id]).length;return {n,total:a.length,p:Math.round(100*n/a.length)}}function roleProgress(){let r=ROLE_PATHS[data.role]||ROLE_PATHS.frontend,skillSteps=r.skills.flatMap(k=>K.find(t=>t[0]===k)[3].map((_,i)=>k+i)),sd=skillSteps.filter(k=>data.skill[k]).length,checks=r.project.checks.map((_,i)=>data.projects[data.role+'-'+i]),pd=checks.filter(Boolean).length;return {skillDone:sd,skillTotal:skillSteps.length,projectDone:pd,projectTotal:checks.length,p:Math.round((sd/skillSteps.length*50)+(pd/checks.length*50))}}function readiness(){return roleProgress().p}
