function splitAccordion(el,items){let open=-1;el.innerHTML=`<ul class="sa">${items.map((x,i)=>`<li><div class="sai"><button class="sah" aria-expanded="false"><span class="saic">${x[0]}</span><b>${esc(x[1])}</b><span class="sach">⌄</span></button><div class="sab"><div><p>${esc(x[2])}</p></div></div></div></li>`).join('')}</ul>`;const lis=[...el.querySelectorAll('li')],n=lis.length;const paint=()=>lis.forEach((li,i)=>{const s=li.firstElementChild,o=i===open,f=i===0,l=i===n-1,bo=open>=0&&i===open-1,ao=open>=0&&i===open+1,alone=(ao&&l)||(bo&&f);let tl=0,tr=0,bl=0,br=0;if(o||alone)tl=tr=bl=br=20;else if(bo)bl=br=20;else if(ao)tl=tr=20;else if(f)tl=tr=20;else if(l)bl=br=20;s.style.borderRadius=`${tl}px ${tr}px ${br}px ${bl}px`;s.style.borderTopWidth=(f||ao||o)?'1px':'0px';s.style.borderBottomWidth=(l||bo||o)?'1px':'0px';s.style.marginBlock=o?'10px':'0px';const b=s.querySelector('.sab');b.style.height=o?b.firstElementChild.scrollHeight+'px':'0px';b.style.opacity=o?1:0;s.querySelector('.sach').style.transform=o?'rotate(180deg)':'none';s.querySelector('.sah').setAttribute('aria-expanded',o)});el.onclick=e=>{const b=e.target.closest('.sah');if(!b)return;const i=lis.indexOf(b.closest('li'));open=open===i?-1:i;paint()};paint()}
